import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const mount=document.querySelector('#game');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0xc87c50);
scene.fog=new THREE.FogExp2(0xc87c50,.0038);
const camera=new THREE.PerspectiveCamera(62,innerWidth/innerHeight,.1,550);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});
renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xffdfb1,0x644333,2.1));
const sun=new THREE.DirectionalLight(0xffcb8b,3.2);sun.position.set(-80,110,45);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-120;sun.shadow.camera.right=120;sun.shadow.camera.top=120;sun.shadow.camera.bottom=-120;sun.shadow.bias=-.0002;scene.add(sun);
const fill=new THREE.DirectionalLight(0x9ca9be,.7);fill.position.set(45,35,-80);scene.add(fill);
const mats={sand:new THREE.MeshStandardMaterial({color:0xb98455,roughness:1}),darkSand:new THREE.MeshStandardMaterial({color:0x73513a,roughness:1}),wood:new THREE.MeshStandardMaterial({color:0x684630,roughness:.92}),lightWood:new THREE.MeshStandardMaterial({color:0xb18356,roughness:.94}),plank:new THREE.MeshStandardMaterial({color:0x8c6543,roughness:.9}),roof:new THREE.MeshStandardMaterial({color:0x49352c,roughness:.95}),cream:new THREE.MeshStandardMaterial({color:0xd9c4a0,roughness:.92}),red:new THREE.MeshStandardMaterial({color:0x8a4432,roughness:.9}),green:new THREE.MeshStandardMaterial({color:0x53634b,roughness:.95}),black:new THREE.MeshStandardMaterial({color:0x231c17,roughness:.8}),leather:new THREE.MeshStandardMaterial({color:0x523729,roughness:.85}),metal:new THREE.MeshStandardMaterial({color:0x54504a,metalness:.72,roughness:.35}),gold:new THREE.MeshStandardMaterial({color:0xb88b4a,metalness:.58,roughness:.36}),glass:new THREE.MeshStandardMaterial({color:0x6f8080,roughness:.25,metalness:.35})};
const boxGeo=new THREE.BoxGeometry(1,1,1),cylGeo=new THREE.CylinderGeometry(1,1,1,10),sphereGeo=new THREE.SphereGeometry(1,12,10);
function box(parent,mat,pos,scale,rot=0){const m=new THREE.Mesh(boxGeo,mat);m.position.set(...pos);m.scale.set(...scale);m.rotation.y=rot;m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cyl(parent,mat,pos,rTop,rBot,h,rot=0){const m=new THREE.Mesh(new THREE.CylinderGeometry(rTop,rBot,h,10),mat);m.position.set(...pos);m.rotation.z=rot;m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,mat,pos,scale){const m=new THREE.Mesh(sphereGeo,mat);m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;parent.add(m);return m}
function group(parent,x=0,y=0,z=0){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);return g}
function rng(seed){let s=seed>>>0;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296}}
const random=rng(9812);
// Rolling ochre basin, carved with shallow natural undulations.
const groundGeo=new THREE.PlaneGeometry(520,520,120,120);groundGeo.rotateX(-Math.PI/2);const p=groundGeo.attributes.position;const colors=[];const c1=new THREE.Color('#a97950'),c2=new THREE.Color('#c29666'),c3=new THREE.Color('#806044');
for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i);let y=Math.sin(x*.035+z*.02)*.65+Math.cos(z*.047-x*.017)*.48+Math.sin(x*.1)*.12;p.setY(i,y);const n=(Math.sin(x*.07+z*.09)+Math.cos(z*.045-x*.06))*.5;const c=n>.45?c2:n<-.65?c3:c1;colors.push(c.r,c.g,c.b)}groundGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));groundGeo.computeVertexNormals();const ground=new THREE.Mesh(groundGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));ground.receiveShadow=true;scene.add(ground);
// Distant mesas create a broad frontier horizon.
function mesa(x,z,w,h,d,color,top=0){const geo=new THREE.CylinderGeometry(w*.68,w,h,7,1);const m=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color,roughness:1}));m.position.set(x,top+h/2-3,z);m.scale.z=d/w;m.rotation.y=random()*1.5;m.receiveShadow=true;scene.add(m);const cap=new THREE.Mesh(new THREE.CylinderGeometry(w*.48,w*.68,Math.max(3,h*.17),7),m.material);cap.position.set(x,top+h-3,z);cap.scale.z=d/w;cap.rotation.y=m.rotation.y;scene.add(cap)}
for(let i=0;i<32;i++){const angle=i/32*Math.PI*2;const r=194+random()*35;mesa(Math.cos(angle)*r,-18+Math.sin(angle)*r,15+random()*24,15+random()*32,18+random()*23,['#805942','#9b6b49','#73533e','#ad7952'][i%4])}
// scrub, dry grass, rocks, and iconic saguaro silhouettes
function cactus(x,z,s=1){const g=group(scene,x,0,z);cyl(g,mats.green,[0,1.7*s,0],.32*s,.37*s,3.4*s);cyl(g,mats.green,[-.5*s,1.5*s,0],.19*s,.23*s,1.6*s,Math.PI/2);cyl(g,mats.green,[-.85*s,2.05*s,0],.18*s,.2*s,.85*s);cyl(g,mats.green,[.48*s,2.15*s,0],.19*s,.23*s,1.35*s,-Math.PI/2);cyl(g,mats.green,[.95*s,2.55*s,0],.17*s,.19*s,.8*s);}
function rock(x,z,s){const m=new THREE.Mesh(new THREE.DodecahedronGeometry(s,0),new THREE.MeshStandardMaterial({color:['#8c674a','#a17b5b','#6d5747'][Math.floor(random()*3)],roughness:1}));m.position.set(x,s*.48,z);m.scale.set(1,.55,.72);m.rotation.y=random()*4;m.castShadow=true;m.receiveShadow=true;scene.add(m)}
for(let i=0;i<200;i++){let x=(random()-.5)*350,z=(random()-.5)*350;if(Math.abs(x)<20&&z<10&&z>-145)continue;if(random()<.36)cactus(x,z,.55+random()*.85);else rock(x,z,.25+random()*1.1)}
function tumbleweed(x,z){const g=group(scene,x,.55,z);const m=new THREE.Mesh(new THREE.IcosahedronGeometry(.55,1),new THREE.MeshStandardMaterial({color:0x87623d,wireframe:true}));g.add(m);g.userData.weed=true;scene.add(g)}
for(let i=0;i<14;i++)tumbleweed((random()-.5)*130,(random()-.5)*180);

