for(let i=0;i<14;i++)tumbleweed((random()-.5)*130,(random()-.5)*180);
// Frontier town: a dusty main street, false-front saloon, general store and sheriff's office.
function building(x,z,w,h,body,sign,front='-z'){
 const g=group(scene,x,0,z);box(g,body,[0,h/2,0],[w,h,w*.66]);box(g,mats.cream,[0,h*.93,-w*.335],[w*1.04,h*.28,.14]);
 box(g,mats.roof,[0,h+.04,0],[w*1.15,.34,w*.78]);box(g,mats.plank,[0,.33,-w*.39],[w*1.13,.22,.46]);
 for(let px of [-w*.42,w*.42])box(g,mats.wood,[px,1.65,-w*.42],[.13,3.3,.14]);
 box(g,mats.black,[0,1.18,-w*.337],[1.35,2.25,.13]);box(g,mats.lightWood,[0,1.18,-w*.418],[1.12,2.15,.08]);
 for(let px of [-w*.28,w*.28]){box(g,mats.black,[px,2.8,-w*.34],[.95,.9,.13]);box(g,mats.glass,[px,2.8,-w*.415],[.76,.7,.04]);box(g,mats.wood,[px,2.8,-w*.445],[.09,.84,.05]);box(g,mats.wood,[px,2.8,-w*.445],[.82,.08,.05]);}
 const signMesh=box(g,mats.wood,[0,h*.67,-w*.5],[w*.84,.55,.12]);
 const canvas=document.createElement('canvas');canvas.width=512;canvas.height=128;const ctx=canvas.getContext('2d');ctx.fillStyle='#755039';ctx.fillRect(0,0,512,128);ctx.strokeStyle='#d5b887';ctx.lineWidth=7;ctx.strokeRect(8,8,496,112);ctx.fillStyle='#f0d7aa';ctx.font='bold 54px Georgia';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(sign,256,66);const tex=new THREE.CanvasTexture(canvas);const board=new THREE.Mesh(new THREE.PlaneGeometry(w*.81,.48),new THREE.MeshBasicMaterial({map:tex}));board.position.set(0,h*.67,-w*.565);g.add(board);
 for(let i=0;i<6;i++)box(g,mats.plank,[-w*.42+i*w*.168,.47,-w*.57],[w*.16,.07,.45]);
 return g;
}
building(-11,-43,10,7.2,mats.red,'THE LAST CHANCE');building(11,-43,9,6.6,mats.cream,'GENERAL STORE');building(-12,-63,9,6.4,mats.lightWood,'LIVERY');const sheriffOffice=building(8,-62,9,6.6,mats.cream,'SHERIFF');
// Hitching rail, barrels, crates, lanterns and a water trough bring the street to life.
for(let z of [-38,-46,-55,-64,-72]){box(scene,mats.wood,[-19,.65,z],[.18,1.3,.18]);box(scene,mats.wood,[-16,.65,z],[.18,1.3,.18]);box(scene,mats.plank,[-17.5,1.05,z],[3,.16,.18]);}
for(let i=0;i<10;i++){let x=(i%2?1:-1)*(7+random()*11),z=-36-Math.floor(i/2)*8;const b=cyl(scene,mats.wood,[x,.55,z],.43,.43,1.1);b.rotation.x=Math.PI/2;box(scene,mats.plank,[x+1,.45,z+.7],[1,.9,.9],random()*.2)}
box(scene,mats.wood,[-6,.38,-69],[2.5,.75,1.1]);box(scene,mats.glass,[-6,.83,-69],[2.3,.08,.9]);
// A cowboy silhouette, composed from stylized frontier gear.
function makeCowboy(coatMat=mats.leather,hatMat=mats.black){const g=group(scene);const body=group(g,0,0,0);cyl(body,coatMat,[0,1.05,0],.28,.39,.87);sphere(body,mats.cream,[0,1.69,0],[.23,.27,.22]);cyl(body,hatMat,[0,1.98,0],.35,.35,.09);cyl(body,hatMat,[0,2.08,0],.22,.25,.19);
 for(let side of [-1,1]){cyl(body,mats.black,[side*.14,.42,0],.11,.14,.67);cyl(body,mats.leather,[side*.14,.13,.025],.14,.16,.18);cyl(body,coatMat,[side*.36,1.22,0],.1,.12,.58,side*.16);sphere(body,mats.cream,[side*.41,.9,-.005],[.095,.11,.09]);}
 box(body,mats.gold,[.23,1.04,-.24],[.16,.27,.08]);box(body,mats.wood,[.43,.91,-.21],[.13,.27,.1],-.2);
 g.userData.body=body;return g;}
const playerGroup=makeCowboy(new THREE.MeshStandardMaterial({color:0x684d38,roughness:.92}),new THREE.MeshStandardMaterial({color:0x29221e,roughness:.9}));
const sheriff=makeCowboy(new THREE.MeshStandardMaterial({color:0x58634a,roughness:.9}),new THREE.MeshStandardMaterial({color:0x3c3128,roughness:.9}));sheriff.position.set(7,0,-58);sheriff.rotation.y=Math.PI;
// Saddled horse with articulated-looking legs and a working mount interaction.
function makeHorse(){const g=group(scene);const brown=new THREE.MeshStandardMaterial({color:0x593b2b,roughness:.95});const dark=new THREE.MeshStandardMaterial({color:0x30251e,roughness:.93});const cream=new THREE.MeshStandardMaterial({color:0x7d5b41,roughness:.95});sphere(g,brown,[0,1.35,0],[.62,.55,1.05]);sphere(g,brown,[0,1.9,-.68],[.34,.66,.36]);sphere(g,brown,[0,2.47,-.82],[.32,.37,.38]);sphere(g,dark,[0,2.38,-1.12],[.2,.19,.3]);for(let s of [-1,1]){sphere(g,mats.black,[s*.22,2.54,-1.08],[.055,.06,.055]);for(let z of [-.65,.68])cyl(g,brown,[s*.35,.7,z],.13,.17,1.22);}
 box(g,mats.leather,[0,1.92,-.1],[.85,.16,.75]);box(g,mats.gold,[0,1.79,-.08],[.86,.13,.85]);box(g,mats.leather,[0,2.02,-.64],[.58,.12,.38]);const tail=cyl(g,dark,[0,1.36,1.06],.08,.14,.95,.25);tail.rotation.x=.25;g.visible=false;return g;}
const horse=makeHorse();horse.position.set(2,0,8);const horsePosition=new THREE.Vector3(2,0,8);
// Sheriff's star and overhead mission marker.
const badge=new THREE.Mesh(new THREE.CircleGeometry(.17,5),mats.gold);badge.position.set(7,1.12,-58.25);scene.add(badge);
function marker(color=0xe0aa67){const g=group(scene);const ring=new THREE.Mesh(new THREE.TorusGeometry(.8,.055,8,32),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.85}));ring.rotation.x=Math.PI/2;ring.position.y=.12;g.add(ring);const beam=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,2.8,6),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.35}));beam.position.y=1.6;g.add(beam);const top=new THREE.Mesh(new THREE.OctahedronGeometry(.2),new THREE.MeshBasicMaterial({color}));top.position.y=3.1;g.add(top);return g}
const objectiveMarker=marker();objectiveMarker.position.set(7,0,-58);

