const objectiveMarker=marker();objectiveMarker.position.set(7,0,-58);
// A bandit camp among the red rocks; the satchel is the proof that brings the story home.
for(let i=0;i<5;i++){const x=-9+i*4.5,z=-133-(i%2)*5;const pole=cyl(scene,mats.wood,[x,1.9,z],.08,.08,3.8);box(scene,i%2?mats.red:mats.cream,[x,2.7,z],[2.5,1.4,.08],(i%2?.28:-.24));}
const campfire=group(scene,0,0,-136);for(let i=0;i<3;i++)cyl(campfire,mats.wood,[Math.cos(i*2.1)*.35,.17,Math.sin(i*2.1)*.35],.09,.12,.95,Math.PI/2+i*.4);
const fireLight=new THREE.PointLight(0xff7939,1.8,14);fireLight.position.set(0,1.1,0);campfire.add(fireLight);const flame=new THREE.Mesh(new THREE.ConeGeometry(.26,.9,7),new THREE.MeshBasicMaterial({color:0xff9a43}));flame.position.y=.56;campfire.add(flame);
const satchel=group(scene,0,0,-139);box(satchel,mats.leather,[0,.28,0],[.7,.45,.32]);box(satchel,mats.gold,[0,.48,-.01],[.5,.04,.34]);satchel.visible=false;
const enemySpots=[[-7,-129],[7,-132],[-1,-139],[11,-143],[-12,-143]];const enemies=[];
for(let i=0;i<enemySpots.length;i++){const e=makeCowboy(new THREE.MeshStandardMaterial({color:['#6d352b','#39433b','#74513b','#553a32','#77705b'][i],roughness:.96}),new THREE.MeshStandardMaterial({color:0x28201b,roughness:.9}));e.position.set(enemySpots[i][0],0,enemySpots[i][1]);e.visible=false;e.userData.health=2;e.userData.alive=true;e.userData.cooldown=1+random()*2;e.userData.strafe=random()<.5?-1:1;enemies.push(e);}
