let audioContext=null;function playShot(){try{audioContext??=new AudioContext();if(audioContext.state==='suspended')audioContext.resume();const t=audioContext.currentTime;const osc=audioContext.createOscillator(),gain=audioContext.createGain(),filter=audioContext.createBiquadFilter();osc.type='triangle';osc.frequency.setValueAtTime(125,t);osc.frequency.exponentialRampToValueAtTime(38,t+.16);filter.type='lowpass';filter.frequency.value=750;gain.gain.setValueAtTime(.26,t);gain.gain.exponentialRampToValueAtTime(.001,t+.22);osc.connect(filter).connect(gain).connect(audioContext.destination);osc.start(t);osc.stop(t+.23)}catch{}}
function makeTracer(start,end){const points=[start.clone(),end.clone()];const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),tracerMaterial.clone());scene.add(line);tracers.push({line,life:.085})}
function shoot(){if(!started||paused||dead||reloading)return;if(ammo<=0){message('Empty cylinder · press R to reload.',1200);return}ammo--;ammoCount.textContent=ammo;playShot();const reticle=document.querySelector('.reticle');reticle.classList.add('firing');setTimeout(()=>reticle.classList.remove('firing'),95);raycaster.setFromCamera(new THREE.Vector2(0,0),camera);const hit=raycaster.intersectObjects(enemies.filter(e=>e.visible&&e.userData.alive),true)[0];let end=raycaster.ray.origin.clone().addScaledVector(raycaster.ray.direction,60);if(hit){end.copy(hit.point);const enemy=enemies.find(e=>e.getObjectById(hit.object.id));if(enemy){enemy.userData.health--;enemy.userData.hitFlash=.14;enemy.traverse(o=>{if(o.isMesh&&o.material.color){o.userData.originalColor=o.material.color.getHex();o.material.color.setHex(0xb87550)}});if(enemy.userData.health<=0){enemy.userData.alive=false;enemy.userData.deadTimer=0;message('Bandit down.',1000);if(enemies.every(e=>!e.userData.alive)){satchel.visible=true;stage=2;setObjective('THE MISSING LEDGER','Search the satchel by the campfire.',new THREE.Vector3(0,0,-139));message('The camp is quiet. Something glints beside the fire.',3300)}}}}
makeTracer(camera.position.clone().addScaledVector(raycaster.ray.direction,.8),end);}
function reload(){if(reloading||ammo===6||reserve<=0||!started)return;reloading=true;message('Reloading…',900);setTimeout(()=>{const n=Math.min(6-ammo,reserve);ammo+=n;reserve-=n;ammoCount.textContent=ammo;reloading=false},1050)}
