function resetPlayer(){health=100;healthFill.style.width='100%';healthNumber.textContent='100';player.pos.set(0,0,8);dead=false;mounted=false;playerGroup.visible=true;horse.visible=false;if(stage===0){ammo=6;reserve=24}ammoCount.textContent=ammo;}

// Third-person western controls: mouse orbit, WASD movement, and a centered revolver shot.
renderer.domElement.addEventListener('click',()=>{if(started&&!paused&&!dead&&innerWidth>700&&document.pointerLockElement!==renderer.domElement)renderer.domElement.requestPointerLock?.()});
addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement&&!paused){player.yaw-=e.movementX*.00235;player.pitch=THREE.MathUtils.clamp(player.pitch-e.movementY*.0018,-.52,.23)}});
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyE'&&!e.repeat)doInteract();if(e.code==='KeyR'&&!e.repeat)reload();if(e.code==='KeyM'&&!e.repeat)toggleMap();if(e.code==='Escape'&&started)togglePause();if(e.code==='Enter'&&dead)resetPlayer()});addEventListener('keyup',e=>keys[e.code]=false);
renderer.domElement.addEventListener('pointerdown',e=>{if(e.button===0&&started&&!paused)shoot()});
function toggleMap(){document.querySelector('#map-panel').classList.toggle('hidden')};function togglePause(){paused=!paused;document.querySelector('#pause-overlay').classList.toggle('hidden',!paused);if(paused&&document.pointerLockElement)document.exitPointerLock()}
document.querySelector('#map-button').addEventListener('click',toggleMap);document.querySelector('#close-map').addEventListener('click',toggleMap);document.querySelector('#resume-button').addEventListener('click',()=>{paused=false;document.querySelector('#pause-overlay').classList.add('hidden')});
document.querySelector('#start-button').addEventListener('click',()=>{started=true;titleScreen.classList.add('hidden');ui.classList.remove('hidden');setObjective('THE OLD TRAIL','Ride into Coyote Creek and speak with Sheriff Miller.',new THREE.Vector3(7,0,-58));document.querySelector('#chapter-card').classList.remove('hidden');setTimeout(()=>document.querySelector('#chapter-card').classList.add('hidden'),3200);if(innerWidth>700)renderer.domElement.requestPointerLock?.();message('Find your horse, or ride on foot. E to interact.',3600)});

