function shoot(){
 if(!started||paused||dead||reloading)return;
 if(ammo<=0){message('Empty cylinder · press R to reload.',1200);return}
 ammo--;ammoCount.textContent=ammo;playShot();
 const reticle=document.querySelector('.reticle');reticle.classList.add('firing');setTimeout(()=>reticle.classList.remove('firing'),95);
 raycaster.setFromCamera(new THREE.Vector2(0,0),camera);
 const liveEnemies=enemies.filter(e=>e.visible&&e.userData.alive);
 let hit=raycaster.intersectObjects(liveEnemies,true)[0];
 // Gentle aim assist keeps the revolver usable with a third-person camera and touch controls.
 if(!hit){let best=Infinity;for(const candidate of liveEnemies){
  const aimPoint=candidate.position.clone().add(new THREE.Vector3(0,1.3,0));
  const along=aimPoint.clone().sub(raycaster.ray.origin).dot(raycaster.ray.direction);
  if(along<=0||along>raycaster.far)continue;
  const closest=raycaster.ray.origin.clone().addScaledVector(raycaster.ray.direction,along);
  const miss=closest.distanceTo(aimPoint);
  const tolerance=5.5+Math.min(along,60)*.025;
  if(miss<=tolerance&&miss<best){best=miss;let mesh=null;candidate.traverse(o=>{if(!mesh&&o.isMesh)mesh=o});if(mesh)hit={point:aimPoint,object:mesh}}
 }}
 let end=raycaster.ray.origin.clone().addScaledVector(raycaster.ray.direction,60);
 if(hit){end.copy(hit.point);const enemy=enemies.find(e=>e.getObjectById(hit.object.id));if(enemy){
  enemy.userData.health--;enemy.userData.hitFlash=.22;
  enemy.traverse(o=>{if(o.isMesh&&o.material.color){if(o.userData.originalColor===undefined)o.userData.originalColor=o.material.color.getHex();o.material.color.setHex(0xb87550)}});
  if(enemy.userData.health<=0){enemy.userData.alive=false;enemy.userData.deadTimer=0;message('Bandit down.',1000);
   if(enemies.every(e=>!e.userData.alive)){satchel.visible=true;stage=2;setObjective('THE MISSING LEDGER','Search the satchel by the campfire.',new THREE.Vector3(0,0,-139));message('The camp is quiet. Something glints beside the fire.',3300)}
  }else message('Hit · bandit wounded.',700);
 }}
 makeTracer(camera.position.clone().addScaledVector(raycaster.ray.direction,.8),end);
}

